      int length = text.indexOf(".");
      addClassToken(index, length, qualifiedName.substring(0, qualifiedName.indexOf("$", pos)));
      pos = qualifiedName.indexOf("$", pos) + 1;
      text = text.substring(length + 1);
      index += length + 1;
