  public void copyEntry(String source, String path, String archiveName, String entryName) {
    if (!checkEntry(entryName))
      return;

    try {
      ZipFile srcArchive = this.openZips.get(source);
      ZipEntry entry = srcArchive.getEntry(entryName);
      if (entry != null) {
