            Exprent exprCore = exprent;

            if (exprent instanceof ExitExprent) {
              ExitExprent exexpr = (ExitExprent)exprent;
              if (exexpr.getExitType() == ExitExprent.Type.RETURN && exexpr.getValue() != null) {
                exprCore = exexpr.getValue();
