          int count = 0;
          StructClass stClass = DecompilerContext.getStructContext().getClass(classname);
          if (stClass != null) {
            List<StructMethod> customMatchedDescriptors = getMatchedDescriptors(false, (mt, md) -> {
              if (md.params.length == descriptor.params.length) {
