  public void writeClass(ClassNode node, TextBuffer buffer, int indent) {
    ReferenceAwareRetentionState state = DecompilerContext.getContextProperty(REFERENCE_AWARE_RETENTION_STATE);
    if (node.type == ClassNode.Type.ROOT && state == null &&
      DecompilerContext.getOption(IFernflowerPreferences.REFERENCE_AWARE_SYNTHETIC_RETENTION)) {
      writeClassWithReferenceAwareRetention(node, buffer, indent);
    }
    else {
      writeClassInternal(node, buffer, indent, state == null || state.process);
    }
  }

  private void writeClassWithReferenceAwareRetention(ClassNode node, TextBuffer buffer, int indent) {
    ReferenceAwareRetentionState previous = DecompilerContext.getContextProperty(REFERENCE_AWARE_RETENTION_STATE);
    ReferenceAwareRetentionState state = new ReferenceAwareRetentionState();
    DecompilerContext.setProperty(REFERENCE_AWARE_RETENTION_STATE, state);

    try {
      TextBuffer rendered = new TextBuffer(ClassesProcessor.AVERAGE_CLASS_SIZE);
      writeClassInternal(node, rendered, indent, true);

      collectRetentionCandidates(node, state.candidates, new HashSet<>());

      while (true) {
        Set<RetentionMember> referenced = new HashSet<>();
        collectReferencedMembers(rendered, state.candidates, referenced);

        if (!state.retained.addAll(referenced)) {
          buffer.append(rendered);
          return;
        }

        state.process = false;
        rendered = new TextBuffer(ClassesProcessor.AVERAGE_CLASS_SIZE);
        writeClassInternal(node, rendered, indent, false);
      }
    }
    finally {
      DecompilerContext.setProperty(REFERENCE_AWARE_RETENTION_STATE, previous);
    }
  }

