+  private boolean shouldRetain(RetentionMember member) {
+    ReferenceAwareRetentionState state = DecompilerContext.getContextProperty(REFERENCE_AWARE_RETENTION_STATE);
+    return state != null && state.candidates.contains(member) && state.retained.contains(member);
